import { useMemo } from 'react'
import { useQuery } from '@tanstack/react-query'
import { useNavigate } from '@tanstack/react-router'
import { fetchProducts, Product } from './products'

interface CartItem {
  productId: number
  quantity: number
}

function parseCart(cart: string | undefined): CartItem[] {
  if (!cart) return []
  return cart
    .split(',')
    .map((part) => part.trim())
    .filter(Boolean)
    .map((part) => {
      const [idStr, qtyStr] = part.split(':')
      const productId = Number(idStr)
      const quantity = Number(qtyStr) || 0
      if (!Number.isFinite(productId) || quantity <= 0) return null
      return { productId, quantity }
    })
    .filter((x): x is CartItem => x !== null)
}

function serializeCart(items: CartItem[]): string {
  return items.map((i) => `${i.productId}:${i.quantity}`).join(',')
}

export default function App() {
  const navigate = useNavigate({ from: '/' })

  const { data: products, isLoading, error } = useQuery<Product[]>({
    queryKey: ['products'],
    queryFn: fetchProducts,
  })

  // Read cart from URL
  const searchParams = new URLSearchParams(window.location.search)
  const cartString = searchParams.get('cart') ?? undefined
  const cartItems = useMemo(() => parseCart(cartString), [cartString])

  const updateCart = (newItems: CartItem[]) => {
    const serialized = serializeCart(newItems)
    navigate({
      to: '/',
      search: (prev: Record<string, unknown>) => ({
        ...prev,
        cart: serialized || undefined,
      }),
    })
  }

  const addToCart = (productId: number) => {
    const existing = cartItems.find((i) => i.productId === productId)
    let next: CartItem[]
    if (existing) {
      next = cartItems.map((i) =>
        i.productId === productId ? { ...i, quantity: i.quantity + 1 } : i,
      )
    } else {
      next = [...cartItems, { productId, quantity: 1 }]
    }
    updateCart(next)
  }

  const incrementItem = (productId: number) => {
    const next = cartItems.map((i) =>
      i.productId === productId ? { ...i, quantity: i.quantity + 1 } : i,
    )
    updateCart(next)
  }

  const decrementItem = (productId: number) => {
    const next = cartItems
      .map((i) =>
        i.productId === productId ? { ...i, quantity: i.quantity - 1 } : i,
      )
      .filter((i) => i.quantity > 0)
    updateCart(next)
  }

  const removeItem = (productId: number) => {
    updateCart(cartItems.filter((i) => i.productId !== productId))
  }

  const clearCart = () => updateCart([])

  const cartDetails = useMemo(() => {
    if (!products) return []
    return cartItems
      .map((item) => {
        const product = products.find((p) => p.id === item.productId)
        if (!product) return null
        return {
          ...item,
          product,
          subtotal: product.price * item.quantity,
        }
      })
      .filter((x): x is { product: Product; productId: number; quantity: number; subtotal: number } => x !== null)
  }, [cartItems, products])

  const total = cartDetails.reduce((sum, item) => sum + item.subtotal, 0)
  const totalItems = cartDetails.reduce((sum, item) => sum + item.quantity, 0)

  return (
    <div style={{ maxWidth: 1100, margin: '0 REDACTED', padding: '20px', fontFamily: 'sans-serif' }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '2px solid #eee', paddingBottom: 10, marginBottom: 20 }}>
        <h1 style={{ margin: 0 }}>🛒 E-commerce Store</h1>
        <div>Cart: <strong>{totalItems}</strong> item(s)</div>
      </header>

      <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: 20 }}>
        <section>
          <h2>Products</h2>
          {isLoading && <p>Loading products…</p>}
          {error && <p>Error loading products</p>}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(REDACTED-fill, minmax(220px, 1fr))', gap: 15 }}>
            {products?.map((product) => {
              const inCart = cartItems.find((i) => i.productId === product.id)
              return (
                <div key={product.id} style={{ border: '1px solid #ddd', borderRadius: 8, padding: 12, background: '#fff' }}>
                  <img src={product.image} alt={product.name} style={{ width: '100%', borderRadius: 4 }} />
                  <h3 style={{ margin: '10px 0 4px' }}>{product.name}</h3>
                  <p style={{ margin: '0 0 6px', color: '#555', fontSize: 14 }}>{product.description}</p>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: 8 }}>
                    <strong>${product.price.toFixed(2)}</strong>
                    <button
                      onClick={() => addToCart(product.id)}
                      style={{
                        background: inCart ? '#28a745' : '#007bff',
                        color: '#fff',
                        border: 'none',
                        padding: '6px 12px',
                        borderRadius: 4,
                        cursor: 'pointer',
                      }}
                    >
                      {inCart ? `In Cart (${inCart.quantity})` : 'Add to Cart'}
                    </button>
                  </div>
                </div>
              )
            })}
          </div>
        </section>

        <aside style={{ border: '1px solid #ddd', borderRadius: 8, padding: 16, background: '#fafafa', alignSelf: 'start' }}>
          <h2 style={{ marginTop: 0 }}>Your Cart</h2>
          {cartDetails.length === 0 && <p style={{ color: '#777' }}>Your cart is empty.</p>}
          {cartDetails.map((item) => (
            <div key={item.productId} style={{ borderBottom: '1px solid #eee', padding: '8px 0' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <strong>{item.product.name}</strong>
                <span>${item.subtotal.toFixed(2)}</span>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginTop: 4 }}>
                <button onClick={() => decrementItem(item.productId)} style={qtyBtn}>−</button>
                <span style={{ minWidth: 20, textAlign: 'center' }}>{item.quantity}</span>
                <button onClick={() => incrementItem(item.productId)} style={qtyBtn}>+</button>
                <button onClick={() => removeItem(item.productId)} style={{ ...qtyBtn, marginLeft: 'REDACTED', background: '#dc3545', color: '#fff' }}>Remove</button>
              </div>
            </div>
          ))}
          {cartDetails.length > 0 && (
            <>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 12, fontSize: 18 }}>
                <strong>Total:</strong>
                <strong>${total.toFixed(2)}</strong>
              </div>
              <button
                onClick={clearCart}
                style={{ marginTop: 10, width: '100%', padding: 8, background: '#6c757d', color: '#fff', border: 'none', borderRadius: 4, cursor: 'pointer' }}
              >
                Clear Cart
              </button>
            </>
          )}
        </aside>
      </div>

      <footer style={{ marginTop: 30, padding: 10, background: '#f4f4f4', borderRadius: 4, fontSize: 12, color: '#555' }}>
        <div>Current URL: <code>{window.location.href}</code></div>
      </footer>
    </div>
  )
}

const qtyBtn: React.CSSProperties = {
  padding: '2px 8px',
  border: '1px solid #ccc',
  borderRadius: 4,
  background: '#fff',
  cursor: 'pointer',
}
EOF
",
      "duration": 0.1
