                <button onClick={() => removeItem(item.productId)} style={{ ...qtyBtn, marginLeft: 'REDACTED', background: '#dc3545', color: '#fff' }}>Remove</button>
              </div>
            </div>
          ))}
          {cartDetails.length > 0 && (
            <>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 12, fontSize: 18 }}>
                <strong>Total:</strong>
                <strong>${total.toFixed(2)}</strong>
              </div>
              <button
                onClick={clearCart}
                style={{ marginTop: 10, width: '100%', padding: 8, background: '#6c757d', color: '#fff', border: 'none', borderRadius: 4, cursor: 'pointer' }}
              >
                Clear Cart
              </button>
            </>
          )}
        </aside>
      </div>

      <footer style={{ marginTop: 30, padding: 10, background: '#f4f4f4', borderRadius: 4, fontSize: 12, color: '#555' }}>
        <div>Current URL: <code>{window.location.href}</code></div>
      </footer>
    </div>
  )
}

